<script>
(()=>{const $=id=>document.getElementById(id);function holidaySet(){return new Set($('holidays').value.split(/[\s,]+/).map(x=>x.trim()).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)))}function key(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}function business(d,hs){return d.getDay()!==0&&d.getDay()!==6&&!hs.has(key(d))}function addBusiness(start,n,hs){const d=new Date(start);const whole=Math.floor(n),frac=n-whole;let c=0;while(c<whole){d.setDate(d.getDate()+1);if(business(d,hs))c++}if(frac>0){do{d.setDate(d.getDate()+1)}while(!business(d,hs));d.setTime(d.getTime()+frac*86400000)}return d}function go(){const s=new Date($('start').value),a=parseFloat($('amount').value),u=$('unit').value;if(!Number.isFinite(s.getTime())||!(a>=0)){$('deadline').textContent='—';$('note').textContent='Enter a valid dispatch time and non-negative SLA amount.';$('note').className='helper danger';return}let d;if(u==='hours')d=new Date(s.getTime()+a*3600000);else if(u==='days')d=new Date(s.getTime()+a*86400000);else d=addBusiness(s,a,holidaySet());$('deadline').textContent=d.toLocaleString();const av=$('actual').value;if(av){const act=new Date(av),diff=act-d;$('status').textContent=diff<=0?'Met':'Missed';const hrs=Math.abs(diff)/3600000;$('variance').textContent=hrs.toFixed(2)+' h '+(diff<=0?'early/on time':'late')}else{$('status').textContent='Not entered';$('variance').textContent='—'}$('note').textContent=u==='business'?'Business-day mode excludes Saturdays, Sundays and the holidays you entered. Cutoff times, carrier calendars and time zones still need to match the governing SLA.':'Elapsed mode uses continuous time from the entered dispatch timestamp.';$('note').className='helper'}['start','amount','unit','actual','holidays'].forEach(id=>$(id).addEventListener('input',go));$('calc').onclick=go;go()})();
</script>
